7328455e-fee8-451f-930f-74e0e0921dbe	62bd238d-2d0b-4cfe-81d3-3716a9470e45	62bd238d-2d0b-4cfe-81d3-3716a9470e45	user	2023년 각월별로 많은 제고량좀 알려줘 	2023년 각월별로 많은 제고량좀 알려줘 	\N	WITH cte_all_parts AS (\n    -- 모든 관련 테이블에서 고유한 part_number를 조회하여 마스터 목록을 생성합니다.\n    SELECT DISTINCT part_number FROM inventory_mgmt.initial_inventory\n    UNION\n    SELECT DISTINCT part_number FROM inventory_mgmt.sales_orders\n    UNION\n    SELECT DISTINCT part_number FROM inventory_mgmt.purchase_orders\n    UNION\n    SELECT DISTINCT part_number FROM inventory_mgmt.products\n),\ncte_all_months_2023 AS (\n    -- 2023년의 모든 월의 시작 날짜를 생성합니다.\n    SELECT generate_series(\n        '2023-01-01'::date,\n        '2023-12-01'::date,\n        '1 month'::interval\n    )::date AS month_start_date\n),\ncte_base_calendar AS (\n    -- 모든 part_number와 2023년의 모든 월 조합을 생성하여 분석의 기준을 마련합니다.\n    SELECT\n        ap.part_number,\n        EXTRACT(YEAR FROM am.month_start_date) AS inventory_year,\n        EXTRACT(MONTH FROM am.month_start_date) AS inventory_month,\n        am.month_start_date\n    FROM cte_all_parts ap\n    CROSS JOIN cte_all_months_2023 am\n),\ncte_initial_stock AS (\n    -- 2022년 12월 31일 기준의 초기 재고(Winter-Snap)를 조회합니다.\n    SELECT\n        part_number,\n        COALESCE(initial_quantity, 0) AS initial_quantity\n    FROM inventory_mgmt.initial_inventory\n    WHERE stock_date = '2022-12-31'::date\n),\ncte_monthly_inflow AS (\n    -- 2023년 각 월별 부품 매입(입고) 수량을 집계합니다.\n    SELECT\n        part_number,\n        EXTRACT(YEAR FROM purchase_date) AS purchase_year,\n        EXTRACT(MONTH FROM purchase_date) AS purchase_month,\n        COALESCE(SUM(purchase_quantity), 0) AS total_purchase_quantity\n    FROM inventory_mgmt.purchase_orders\n    WHERE EXTRACT(YEAR FROM purchase_date) = 2023\n    GROUP BY part_number, EXTRACT(YEAR FROM purchase_date), EXTRACT(MONTH FROM purchase_date)\n),\ncte_monthly_outflow AS (\n    -- 2023년 각 월별 제품 출고(판매) 수량을 집계합니다.\n    SELECT\n        part_number,\n        EXTRACT(YEAR FROM sale_date) AS sale_year,\n        EXTRACT(MONTH FROM sale_date) AS sale_month,\n        COALESCE(SUM(sale_quantity), 0) AS total_sale_quantity\n    FROM inventory_mgmt.sales_orders\n    WHERE EXTRACT(YEAR FROM sale_date) = 2023\n    GROUP BY part_number, EXTRACT(YEAR FROM sale_date), EXTRACT(MONTH FROM sale_date)\n),\ncte_inventory_movements AS (\n    -- 초기 재고와 월별 입고/출고 데이터를 결합하여 각 월의 재고 변동을 계산합니다.\n    SELECT\n        cbc.part_number,\n        cbc.inventory_year,\n        cbc.inventory_month,\n        cbc.month_start_date,\n        COALESCE(cis.initial_quantity, 0) AS initial_stock_at_start_of_2023,\n        COALESCE(cmi.total_purchase_quantity, 0) AS monthly_inflow,\n        COALESCE(cmo.total_sale_quantity, 0) AS monthly_outflow\n    FROM cte_base_calendar cbc\n    LEFT JOIN cte_initial_stock cis\n        ON cbc.part_number = cis.part_number\n    LEFT JOIN cte_monthly_inflow cmi\n        ON cbc.part_number = cmi.part_number\n        AND cbc.inventory_year = cmi.purchase_year\n        AND cbc.inventory_month = cmi.purchase_month\n    LEFT JOIN cte_monthly_outflow cmo\n        ON cbc.part_number = cmo.part_number\n        AND cbc.inventory_year = cmo.sale_year\n        AND cbc.inventory_month = cmo.sale_month\n),\ncte_cumulative_inventory AS (\n    -- 각 part_number별로 2023년 월별 누적 재고량을 계산합니다.\n    -- 재고는 '2022-12-31 초기 재고' + '해당 월까지의 누적 입고' - '해당 월까지의 누적 출고'로 계산됩니다.\n    SELECT\n        part_number,\n        inventory_year,\n        inventory_month,\n        month_start_date,\n        CAST(\n            -- 2023년 시작 시점의 초기 재고를 가져옵니다.\n            FIRST_VALUE(initial_stock_at_start_of_2023) OVER (PARTITION BY part_number ORDER BY month_start_date)\n            -- 해당 월까지의 순 재고 변동(입고 - 출고)을 누적합니다.\n            + SUM(monthly_inflow - monthly_outflow) OVER (PARTITION BY part_number ORDER BY month_start_date)\n        AS NUMERIC) AS cumulative_quantity\n    FROM cte_inventory_movements\n),\ncte_ranked_inventory AS (\n    -- 각 월별로 재고량이 가장 많은 part_number를 찾기 위해 순위를 매깁니다.\n    SELECT\n        part_number,\n        inventory_year,\n        inventory_month,\n        month_start_date,\n        cumulative_quantity,\n        ROW_NUMBER() OVER (PARTITION BY inventory_year, inventory_month ORDER BY cumulative_quantity DESC) AS rn\n    FROM cte_cumulative_inventory\n),\ncte_product_details AS (\n    -- 제품 마스터에서 part_number에 해당하는 description을 조회합니다.\n    SELECT\n        part_number,\n        description\n    FROM inventory_mgmt.products\n)\n-- 최종 결과: 2023년 각 월별로 재고량이 가장 많은 제품의 정보와 재고량을 출력합니다.\nSELECT\n    TO_CHAR(cri.month_start_date, 'YYYY-MM') AS inventory_month,\n    cri.part_number,\n    cpd.description,\n    cri.cumulative_quantity AS highest_inventory_quantity\nFROM cte_ranked_inventory cri\nJOIN cte_product_details cpd\n    ON cri.part_number = cpd.part_number\nWHERE cri.rn = 1 -- 각 월별로 가장 높은 재고량을 가진 제품만 선택합니다.\nORDER BY cri.month_start_date	{"df": null, "answer": "분석 삭제: ❌ Cartesian Product 위험: JOIN 5개, ON 4개", "sql_query": "WITH cte_all_parts AS (\\n    -- 모든 관련 테이블에서 고유한 part_number를 조회하여 마스터 목록을 생성합니다.\\n    SELECT DISTINCT part_number FROM inventory_mgmt.initial_inventory\\n    UNION\\n    SELECT DISTINCT part_number FROM inventory_mgmt.sales_orders\\n    UNION\\n    SELECT DISTINCT part_number FROM inventory_mgmt.purchase_orders\\n    UNION\\n    SELECT DISTINCT part_number FROM inventory_mgmt.products\\n),\\ncte_all_months_2023 AS (\\n    -- 2023년의 모든 월의 시작 날짜를 생성합니다.\\n    SELECT generate_series(\\n        '2023-01-01'::date,\\n        '2023-12-01'::date,\\n        '1 month'::interval\\n    )::date AS month_start_date\\n),\\ncte_base_calendar AS (\\n    -- 모든 part_number와 2023년의 모든 월 조합을 생성하여 분석의 기준을 마련합니다.\\n    SELECT\\n        ap.part_number,\\n        EXTRACT(YEAR FROM am.month_start_date) AS inventory_year,\\n        EXTRACT(MONTH FROM am.month_start_date) AS inventory_month,\\n        am.month_start_date\\n    FROM cte_all_parts ap\\n    CROSS JOIN cte_all_months_2023 am\\n),\\ncte_initial_stock AS (\\n    -- 2022년 12월 31일 기준의 초기 재고(Winter-Snap)를 조회합니다.\\n    SELECT\\n        part_number,\\n        COALESCE(initial_quantity, 0) AS initial_quantity\\n    FROM inventory_mgmt.initial_inventory\\n    WHERE stock_date = '2022-12-31'::date\\n),\\ncte_monthly_inflow AS (\\n    -- 2023년 각 월별 부품 매입(입고) 수량을 집계합니다.\\n    SELECT\\n        part_number,\\n        EXTRACT(YEAR FROM purchase_date) AS purchase_year,\\n        EXTRACT(MONTH FROM purchase_date) AS purchase_month,\\n        COALESCE(SUM(purchase_quantity), 0) AS total_purchase_quantity\\n    FROM inventory_mgmt.purchase_orders\\n    WHERE EXTRACT(YEAR FROM purchase_date) = 2023\\n    GROUP BY part_number, EXTRACT(YEAR FROM purchase_date), EXTRACT(MONTH FROM purchase_date)\\n),\\ncte_monthly_outflow AS (\\n    -- 2023년 각 월별 제품 출고(판매) 수량을 집계합니다.\\n    SELECT\\n        part_number,\\n        EXTRACT(YEAR FROM sale_date) AS sale_year,\\n        EXTRACT(MONTH FROM sale_date) AS sale_month,\\n        COALESCE(SUM(sale_quantity), 0) AS total_sale_quantity\\n    FROM inventory_mgmt.sales_orders\\n    WHERE EXTRACT(YEAR FROM sale_date) = 2023\\n    GROUP BY part_number, EXTRACT(YEAR FROM sale_date), EXTRACT(MONTH FROM sale_date)\\n),\\ncte_inventory_movements AS (\\n    -- 초기 재고와 월별 입고/출고 데이터를 결합하여 각 월의 재고 변동을 계산합니다.\\n    SELECT\\n        cbc.part_number,\\n        cbc.inventory_year,\\n        cbc.inventory_month,\\n        cbc.month_start_date,\\n        COALESCE(cis.initial_quantity, 0) AS initial_stock_at_start_of_2023,\\n        COALESCE(cmi.total_purchase_quantity, 0) AS monthly_inflow,\\n        COALESCE(cmo.total_sale_quantity, 0) AS monthly_outflow\\n    FROM cte_base_calendar cbc\\n    LEFT JOIN cte_initial_stock cis\\n        ON cbc.part_number = cis.part_number\\n    LEFT JOIN cte_monthly_inflow cmi\\n        ON cbc.part_number = cmi.part_number\\n        AND cbc.inventory_year = cmi.purchase_year\\n        AND cbc.inventory_month = cmi.purchase_month\\n    LEFT JOIN cte_monthly_outflow cmo\\n        ON cbc.part_number = cmo.part_number\\n        AND cbc.inventory_year = cmo.sale_year\\n        AND cbc.inventory_month = cmo.sale_month\\n),\\ncte_cumulative_inventory AS (\\n    -- 각 part_number별로 2023년 월별 누적 재고량을 계산합니다.\\n    -- 재고는 '2022-12-31 초기 재고' + '해당 월까지의 누적 입고' - '해당 월까지의 누적 출고'로 계산됩니다.\\n    SELECT\\n        part_number,\\n        inventory_year,\\n        inventory_month,\\n        month_start_date,\\n        CAST(\\n            -- 2023년 시작 시점의 초기 재고를 가져옵니다.\\n            FIRST_VALUE(initial_stock_at_start_of_2023) OVER (PARTITION BY part_number ORDER BY month_start_date)\\n            -- 해당 월까지의 순 재고 변동(입고 - 출고)을 누적합니다.\\n            + SUM(monthly_inflow - monthly_outflow) OVER (PARTITION BY part_number ORDER BY month_start_date)\\n        AS NUMERIC) AS cumulative_quantity\\n    FROM cte_inventory_movements\\n),\\ncte_ranked_inventory AS (\\n    -- 각 월별로 재고량이 가장 많은 part_number를 찾기 위해 순위를 매깁니다.\\n    SELECT\\n        part_number,\\n        inventory_year,\\n        inventory_month,\\n        month_start_date,\\n        cumulative_quantity,\\n        ROW_NUMBER() OVER (PARTITION BY inventory_year, inventory_month ORDER BY cumulative_quantity DESC) AS rn\\n    FROM cte_cumulative_inventory\\n),\\ncte_product_details AS (\\n    -- 제품 마스터에서 part_number에 해당하는 description을 조회합니다.\\n    SELECT\\n        part_number,\\n        description\\n    FROM inventory_mgmt.products\\n)\\n-- 최종 결과: 2023년 각 월별로 재고량이 가장 많은 제품의 정보와 재고량을 출력합니다.\\nSELECT\\n    TO_CHAR(cri.month_start_date, 'YYYY-MM') AS inventory_month,\\n    cri.part_number,\\n    cpd.description,\\n    cri.cumulative_quantity AS highest_inventory_quantity\\nFROM cte_ranked_inventory cri\\nJOIN cte_product_details cpd\\n    ON cri.part_number = cpd.part_number\\nWHERE cri.rn = 1 -- 각 월별로 가장 높은 재고량을 가진 제품만 선택합니다.\\nORDER BY cri.month_start_date", "chart_info": {"type": "none"}}	{}	0	f	2026-03-03 09:41:10.969069+00
